def preprocess(s):
    n = len(s)
    s += s
    lps = [0] * (2 * n)
    j = 0
    for i in range(1, 2 * n):
        while j > 0 and s[i] != s[j]:
            j = lps[j - 1]
        if s[i] == s[j]:
            j += 1
        lps[i] = j
    return lps

def count_cyclical_isomorphic_substrings(s, x):
    n = len(s)
    m = len(x)
    x += x
    lps = preprocess(x)

    count = 0
    j = 0
    for i in range(n):
        while j > 0 and s[i] != x[j]:
            j = lps[j - 1]
        if s[i] == x[j]:
            j += 1
        if j == m:
            count += 1
            j = lps[j - 1]
    return count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    s = data[0]
    n = int(data[1])
    queries = data[2:]

    results = []
    for x in queries:
        results.append(count_cyclical_isomorphic_substrings(s, x))

    for count in results:
        print(count)

if __name__ == "__main__":
    main()
